  const F=`url(#${id})`, L=sh(c1,.3), D=sh(c1,-.35), op=gl&&!met?' fill-opacity=".88"':'', hi=(x,y,w)=>`<path d="M${x},${y} l${w},-${w*.6}" stroke="#fff" stroke-opacity=".8" stroke-width="2.2" stroke-linecap="round"/>`;
